export async function mergeSandbox(sandbox, originalTree) {
  const snapshot = await sandbox.export('/', { format: 'json' });
  const diff = computeFilesystemDiff(originalTree, snapshot);
  for (const { path, content } of diff.added.concat(diff.modified)) {
    await writeToHost(path, content);
  }
  for (const path of diff.deleted) {
    await deleteFromHost(path);
  }
  return diff;
}

